def reachable(g,s):
    seen={s}; stack=[s]
    while stack:
        for v in g[stack.pop()]:
            if v not in seen: seen.add(v); stack.append(v)
    return seen

def greedy_coins(amount):
    used=0
    for coin in (4,3,1):
        used,amount=used+amount//coin,amount%coin
    return used
print(greedy_coins(6))  # 3

def first_feasible(low,high,feasible):
    while low<high:
        mid=(low+high)//2
        if feasible(mid): high=mid
        else: low=mid+1
    return low
